from sqlalchemy.engine import URL, make_url
from sqlalchemy.ext.asyncio import async_sessionmaker, create_async_engine

from dedlainych.config import settings


def async_database_url(value: str) -> URL:
    """Accept the direct PostgreSQL URL generated by Render without exposing credentials."""
    url = make_url(value)
    if url.drivername in {"postgres", "postgresql"}:
        url = url.set(drivername="postgresql+asyncpg")
    return url


def make_database(url: str | None = None):
    address = async_database_url(url or settings().database_url.get_secret_value())
    engine = create_async_engine(address, pool_pre_ping=True)
    return engine, async_sessionmaker(engine, expire_on_commit=False)
